import { generateOrders, toCsv, DATASET_KEY } from "@/lib/assessment/datasets/northwind-commerce";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Serve the synthetic assessment dataset as CSV.
 *
 * The data is generated by us and contains no personal or copyrighted content,
 * so it is downloadable without authentication (candidates need it mid-task).
 */
export async function GET(request: Request) {
  const url = new URL(request.url);
  const key = url.searchParams.get("key") ?? DATASET_KEY;
  if (key !== DATASET_KEY) {
    return Response.json(
      { success: false, error: { code: "NOT_FOUND", message: "Dataset not found." } },
      { status: 404 },
    );
  }

  const csv = toCsv(generateOrders());
  return new Response(csv, {
    headers: {
      "Content-Type": "text/csv; charset=utf-8",
      "Content-Disposition": `attachment; filename="${DATASET_KEY}.csv"`,
      "Cache-Control": "public, max-age=3600",
    },
  });
}
